import{_ as a,c as i,o as e,aM as l}from"./chunks/framework.kKeYZnSg.js";const r="/fe-handbook/assets/Untitled.DMCVatvm.png",n="/fe-handbook/assets/Untitled%201.DZMmu6FV.png",o="/fe-handbook/assets/Untitled%202.Ew0hYxXv.png",s="/fe-handbook/assets/Untitled%203.CqSDxmCR.png",d="/fe-handbook/assets/Untitled%204.D_X-UUr5.png",f=JSON.parse('{"title":"Git工作机制","description":"","frontmatter":{},"headers":[],"relativePath":"other/git/operating-mechanism.md","filePath":"other/git/operating-mechanism.md","lastUpdated":1787488143000}'),h={name:"other/git/operating-mechanism.md"};function c(g,t,m,p,u,_){return e(),i("div",null,t[0]||(t[0]=[l('<h1 id="git工作机制" tabindex="-1">Git工作机制 <a class="header-anchor" href="#git工作机制" aria-label="Permalink to &quot;Git工作机制&quot;">​</a></h1><h2 id="三大区域" tabindex="-1"><strong>三大区域</strong> <a class="header-anchor" href="#三大区域" aria-label="Permalink to &quot;**三大区域**&quot;">​</a></h2><p><img src="'+r+'" alt="Untitled"></p><p><img src="'+n+'" alt="Untitled"></p><h3 id="工作流" tabindex="-1">工作流 <a class="header-anchor" href="#工作流" aria-label="Permalink to &quot;工作流&quot;">​</a></h3><p><img src="'+o+'" alt="Untitled"></p><p><img src="'+s+'" alt="Untitled"></p><p><img src="'+d+'" alt="Untitled"></p><h3 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h3><ul><li>分区：<strong>工作区、暂存区、版本库</strong></li><li>文件分类：<strong>tracked，untracked，ignored</strong>；<strong>staged，unstaged</strong></li><li>会忽略的文件：.gitignore文件中指定的文件、空目录</li></ul><h3 id="数据管理机制" tabindex="-1">数据管理机制 <a class="header-anchor" href="#数据管理机制" aria-label="Permalink to &quot;数据管理机制&quot;">​</a></h3><ul><li>SVN <ul><li>增量式，每个版本保存变化的部分</li></ul></li><li>Git <ul><li>快照流，每个版本保存所有文件的一个快照，如果文件没有修改，文件指针会指向上一个版本的对应文件</li></ul></li></ul><h3 id="哈希算法" tabindex="-1">哈希算法 <a class="header-anchor" href="#哈希算法" aria-label="Permalink to &quot;哈希算法&quot;">​</a></h3><ul><li>是一类加密算法：明文-&gt;密文</li><li>同种哈希算法，不管输入量多大，加密的结果长度一致</li><li>同种哈希算法，只要输入有一点变化，加密结果就会有很大的变化</li><li>哈希算法不可逆</li><li>哈希算法可用于文件校验</li><li>Git底层使用<strong>SHA-1</strong>算法，40个16进制位</li></ul><h3 id="提交的表示" tabindex="-1">提交的表示 <a class="header-anchor" href="#提交的表示" aria-label="Permalink to &quot;提交的表示&quot;">​</a></h3><ul><li>散列id</li><li><strong>HEAD始终指向当前分支的最新提交</strong></li><li>HEAD^ HEAD~ HEAD^~ HEAD^1 HEAD~1 HEAD^1~1 均表示HEAD的第一个父提交</li><li>HEAD^m 控制回退到哪个分支（当HEAD指向的当前提交由多个分支合并而来时）</li><li>HEAD~n 控制回退的步数</li><li>HEAD^2表示 HEAD的第二个父提交</li><li>HEAD~2表示HEAD的第一个父提交的第一个父提交</li></ul>',16)]))}const b=a(h,[["render",c]]);export{f as __pageData,b as default};
